{
  global:
    /* interposers：必须留在动态符号表里，否则 LD_PRELOAD 拦不到 */
    open; open64; openat; openat64; openat2;
    fopen; freopen; close;
    readlink; readlinkat;
    stat; lstat; fstatat; statx; access; faccessat;
    opendir; readdir; readdir64; scandir; scandir64;
    dl_iterate_phdr; dlopen; getenv; secure_getenv;
    /* 公开入口（loaders / tests 会用名字探测） */
    init; performHook; _Z4initv; _Z11performHookv;
    OicqCompileFunctionHook;
    oicq_init; oicq_boot; oicq_entry_path;
    oicq_mangled_init; oicq_mangled_perform;
  local:
    *;
};
